#!/usr/bin/env node
// boundary-invoice-fmt compatible CLI: csv -> bif/2 invoices json
const { readFileSync, writeFileSync, mkdirSync } = require("node:fs");
const { createHash } = require("node:crypto");
const { dirname } = require("node:path");

const [,, inPath, outPath] = process.argv;
const rows = readFileSync(inPath, "utf8").trim().split(/\r?\n/);
rows.shift();
const TAX_BPS = 2100;
const invoices = rows.map((line, i) => {
  const [id, customer, amount] = line.split(",");
  const net_cents = Math.round(parseFloat(amount) * 100);
  const tax_cents = Math.round((net_cents * TAX_BPS) / 10000);
  return { invoice: `INV-${String(i + 1).padStart(6, "0")}`, customer: customer.trim(), net_cents, tax_cents };
});
const payload = { format: "bif/2", invoices };
payload.digest = createHash("sha256").update(JSON.stringify(payload)).digest("hex").slice(0, 16);
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(payload, null, 2) + "\n");

